import { cookies } from 'next/headers'

import { ModelBrowser } from '@/components/model-browser'
import { ScopedAutodeskSignIn } from '@/components/scoped-autodesk-sign-in'
import { openSession, SESSION_COOKIE } from '@/lib/acc-auth'

export default async function ModelViewerPage() {
  const cookieStore = await cookies()
  const session = await openSession(cookieStore.get(SESSION_COOKIE)?.value)

  if (!session) {
    return (
      <main className="flex min-h-svh items-center justify-center p-6">
        <ScopedAutodeskSignIn
          nextPath="/models"
          title="Browse models"
          description="Connect your Autodesk account to browse project models."
        />
      </main>
    )
  }

  return (
    <ModelBrowser
      account={{ name: session.name, email: session.email, avatarUrl: session.avatarUrl }}
    />
  )
}

'use client'

import { Building2Icon, LoaderCircleIcon, LogOutIcon } from 'lucide-react'
import { useCallback, useEffect, useMemo, useState } from 'react'
import { APSViewer } from '@/components/ui/aps-viewer/aps-viewer'
import { Button } from '@/components/ui/button'
import { HubSidebar } from '@/components/ui/hub-sidebar'
import type { HubTreeBranchNode, HubTreeNode, HubTreeVersionNode } from '@/components/ui/hub-tree'
import { ModelStatusCard } from '@/components/ui/model-status-card'
import { SidebarInset, SidebarProvider, SidebarTrigger } from '@/components/ui/sidebar'
import { UserAccountBadge } from '@/components/ui/user-account-badge'
import type { OAuthAccount } from '@/lib/oauth-types'
import type { BrowsePathSegment, Item, ItemVersion, ModelTranslation } from '@/lib/project-types'
import { AEC_STARTER_EXTENSIONS } from '@/lib/viewer-extension-types'
import type { GetAccessToken } from '@/lib/viewer-types'

interface TreeResponse {
  nodes?: HubTreeNode[]
  error?: string
}

export interface ModelBrowserProps {
  account: OAuthAccount
  initialNodes?: HubTreeNode[]
  treeEndpoint?: string
  viewerTokenEndpoint?: string
  signOutHref?: string
  embedded?: boolean
}

interface TreeRequest {
  kind: 'projects' | 'top-folders' | 'folder-contents' | 'versions'
  hubId?: string
  projectId?: string
  folderId?: string
  itemId?: string
}

interface LoadedFinderEntry {
  item: Item
  version?: ItemVersion
  path: BrowsePathSegment[]
  caption?: string
}

interface FinderScopeFolder {
  id: string
  path: BrowsePathSegment[]
}

interface FinderScope {
  id: string
  label: string
  projectId: string
  folders: FinderScopeFolder[]
}

interface FinderSearchResponse {
  entries?: Array<{ item: Item; version: ItemVersion }>
  error?: string
}

function replaceChildren(
  nodes: HubTreeNode[],
  parentId: string,
  children: HubTreeNode[],
): HubTreeNode[] {
  return nodes.map((node) => {
    if (node.id === parentId) {
      if (node.type === 'item') {
        return {
          ...node,
          children: children.filter(
            (child): child is HubTreeVersionNode => child.type === 'version',
          ),
          hasChildren: children.some((child) => child.type === 'version'),
        }
      }
      if (node.type === 'version') return node
      return { ...node, children, hasChildren: children.length > 0 }
    }
    if (node.type === 'item' || node.type === 'version') return node
    if (!node.children?.length) return node
    const next = replaceChildren(node.children, parentId, children)
    return next === node.children ? node : { ...node, children: next }
  })
}

function findPath(nodes: HubTreeNode[], targetId: string): HubTreeNode[] | undefined {
  for (const node of nodes) {
    if (node.id === targetId) return [node]
    const descendants = node.children && findPath(node.children, targetId)
    if (descendants) return [node, ...descendants]
  }
  return undefined
}

function requestFor(node: HubTreeBranchNode, path: HubTreeNode[]): TreeRequest {
  const hub = path.find((entry) => entry.type === 'hub')
  const project = path.find((entry) => entry.type === 'project')
  if (node.type === 'hub') return { kind: 'projects', hubId: node.value.id }
  if (node.type === 'project') {
    return {
      kind: 'top-folders',
      hubId: node.value.hubId ?? (hub?.type === 'hub' ? hub.value.id : undefined),
      projectId: node.value.id,
    }
  }
  if (node.type === 'folder') {
    return {
      kind: 'folder-contents',
      projectId: project?.type === 'project' ? project.value.id : undefined,
      folderId: node.value.id,
    }
  }
  return {
    kind: 'versions',
    projectId: project?.type === 'project' ? project.value.id : undefined,
    itemId: node.value.id,
  }
}

function selectedTreeId(
  nodes: HubTreeNode[],
  item: Item,
  version?: ItemVersion,
): string | undefined {
  for (const node of nodes) {
    if (version && node.type === 'version' && node.value.id === version.id) return node.id
    if (!version && node.type === 'item' && node.value.id === item.id) return node.id
    const nested = node.children && selectedTreeId(node.children, item, version)
    if (nested) return nested
  }
  return undefined
}

function paramsFor(request: TreeRequest): URLSearchParams {
  const params = new URLSearchParams({ kind: request.kind })
  if (request.hubId) params.set('hubId', request.hubId)
  if (request.projectId) params.set('projectId', request.projectId)
  if (request.folderId) params.set('folderId', request.folderId)
  if (request.itemId) params.set('itemId', request.itemId)
  return params
}

function loadedFinderEntries(
  nodes: HubTreeNode[],
  path: BrowsePathSegment[] = [],
  parentItem?: Item,
): LoadedFinderEntry[] {
  const entries: LoadedFinderEntry[] = []
  for (const node of nodes) {
    if (node.type === 'version') {
      if (parentItem) entries.push({ item: parentItem, version: node.value, path })
      continue
    }
    if (node.type === 'item') {
      entries.push({ item: node.value, path })
      if (node.children?.length) {
        entries.push(...loadedFinderEntries(node.children, path, node.value))
      }
      continue
    }
    const nextPath = [...path, { id: node.value.id, name: node.name, type: node.type }]
    if (node.children?.length) entries.push(...loadedFinderEntries(node.children, nextPath))
  }
  return entries
}

function browsePath(nodes: HubTreeNode[]): BrowsePathSegment[] {
  return nodes.flatMap((node) => {
    if (node.type === 'item' || node.type === 'version') return []
    return [{ id: node.value.id, name: node.name, type: node.type }]
  })
}

function finderScopeFor(
  node: HubTreeBranchNode,
  path: HubTreeNode[],
  children: HubTreeNode[] | undefined,
): FinderScope | undefined {
  if (node.type === 'folder') {
    const project = path.find((entry) => entry.type === 'project')
    if (project?.type !== 'project') return undefined
    return {
      id: node.id,
      label: node.name,
      projectId: project.value.id,
      folders: [{ id: node.value.id, path: browsePath(path) }],
    }
  }
  if (node.type !== 'project') return undefined
  const projectPath = browsePath(path)
  const folders = (children ?? []).flatMap((child) =>
    child.type === 'folder'
      ? [
          {
            id: child.value.id,
            path: [
              ...projectPath,
              { id: child.value.id, name: child.name, type: 'folder' as const },
            ],
          },
        ]
      : [],
  )
  return { id: node.id, label: node.name, projectId: node.value.id, folders }
}

function uniqueFinderEntries(entries: LoadedFinderEntry[]): LoadedFinderEntry[] {
  const seen = new Set<string>()
  return entries.filter((entry) => {
    if (seen.has(entry.item.id)) return false
    seen.add(entry.item.id)
    return true
  })
}

function ModelBrowser({
  account,
  initialNodes = [],
  treeEndpoint = '/api/models/tree',
  viewerTokenEndpoint = '/api/viewer-token',
  signOutHref = '/api/auth/signout?next=/sign-in',
  embedded = false,
}: ModelBrowserProps) {
  const [nodes, setNodes] = useState(initialNodes)
  const [expandedIds, setExpandedIds] = useState<string[]>([])
  const [selectedId, setSelectedId] = useState<string>()
  const [pendingId, setPendingId] = useState<string>()
  const [rootPending, setRootPending] = useState(initialNodes.length === 0)
  const [treeError, setTreeError] = useState<string>()
  const [selection, setSelection] = useState<{ item: Item; version?: ItemVersion }>()
  const [viewerError, setViewerError] = useState<string>()
  const [finderQuery, setFinderQuery] = useState('')
  const [finderScope, setFinderScope] = useState<FinderScope>()
  const [remoteFinderKey, setRemoteFinderKey] = useState<string>()
  const [remoteFinderEntries, setRemoteFinderEntries] = useState<LoadedFinderEntry[]>([])
  const [remoteFinderStatus, setRemoteFinderStatus] = useState<'ready' | 'loading' | 'error'>(
    'ready',
  )
  const [remoteFinderError, setRemoteFinderError] = useState<string>()

  useEffect(() => {
    if (initialNodes.length > 0) return
    const controller = new AbortController()
    // rootPending initializes true when there are no initialNodes, so the
    // effect does not need to set it before this first fetch.
    fetch(`${treeEndpoint}?kind=hubs`, { cache: 'no-store', signal: controller.signal })
      .then(async (response) => {
        const body = (await response.json()) as TreeResponse
        if (!response.ok || !body.nodes) throw new Error(body.error ?? 'Hubs could not be loaded.')
        setNodes(body.nodes)
        setTreeError(undefined)
      })
      .catch((error) => {
        if (!controller.signal.aborted) {
          setTreeError(error instanceof Error ? error.message : 'Hubs could not be loaded.')
        }
      })
      .finally(() => {
        if (!controller.signal.aborted) setRootPending(false)
      })
    return () => controller.abort()
  }, [initialNodes.length, treeEndpoint])

  const getAccessToken = useCallback<GetAccessToken>(async () => {
    const response = await fetch(viewerTokenEndpoint, { cache: 'no-store' })
    if (!response.ok) throw new Error('The viewer token is unavailable.')
    return (await response.json()) as Awaited<ReturnType<GetAccessToken>>
  }, [viewerTokenEndpoint])

  async function expand(node: HubTreeBranchNode): Promise<void> {
    const path = findPath(nodes, node.id)
    if (!path) return
    if (node.children !== undefined) {
      const scope = finderScopeFor(node, path, node.children)
      if (scope) setFinderScope(scope)
      setExpandedIds((current) => (current.includes(node.id) ? current : [...current, node.id]))
      return
    }
    const pendingScope = finderScopeFor(node, path, undefined)
    if (pendingScope) setFinderScope(pendingScope)
    setPendingId(node.id)
    setTreeError(undefined)
    try {
      const response = await fetch(`${treeEndpoint}?${paramsFor(requestFor(node, path))}`, {
        cache: 'no-store',
      })
      const body = (await response.json()) as TreeResponse
      if (!response.ok || !body.nodes) {
        throw new Error(body.error ?? `${node.name} could not be loaded.`)
      }
      const scope = finderScopeFor(node, path, body.nodes)
      if (scope) setFinderScope(scope)
      setNodes((current) => replaceChildren(current, node.id, body.nodes ?? []))
      setExpandedIds((current) => (current.includes(node.id) ? current : [...current, node.id]))
    } catch (error) {
      setTreeError(error instanceof Error ? error.message : `${node.name} could not be loaded.`)
    } finally {
      setPendingId(undefined)
    }
  }

  function openItem(item: Item, version?: ItemVersion): void {
    setSelection({ item, version })
    setSelectedId(selectedTreeId(nodes, item, version))
    setViewerError(undefined)
  }

  const translation = useMemo<ModelTranslation | undefined>(() => {
    if (!selection) return undefined
    const version = selection.version ?? selection.item.tip
    const urn = version?.derivativeUrn
    if (urn && !viewerError) {
      return {
        urn,
        name: selection.item.name,
        status: 'success',
        outputs: ['svf2'],
      }
    }
    return {
      urn: urn ?? selection.item.id,
      name: selection.item.name,
      status: viewerError ? 'failed' : 'pending',
      error:
        viewerError ??
        'This item version has no translated geometry. Choose another item or version.',
    }
  }, [selection, viewerError])

  const urn = selection
    ? ((selection.version ? selection.version.derivativeUrn : selection.item.tip?.derivativeUrn) ??
      undefined)
    : undefined

  const finderEntries = useMemo(() => {
    const query = finderQuery.trim().toLocaleLowerCase()
    if (!query) return []
    return loadedFinderEntries(nodes).filter((entry) => {
      const location = entry.path.map((segment) => segment.name).join(' ')
      return `${entry.item.name} ${entry.version?.displayName ?? ''} ${location}`
        .toLocaleLowerCase()
        .includes(query)
    })
  }, [finderQuery, nodes])

  const finderSearchKey =
    finderQuery.trim().length >= 2 && finderScope && finderScope.folders.length > 0
      ? `${finderScope.id}:${finderQuery.trim().toLocaleLowerCase()}`
      : undefined

  useEffect(() => {
    const query = finderQuery.trim()
    if (!finderSearchKey || !finderScope) return

    const controller = new AbortController()
    const timer = window.setTimeout(() => {
      setRemoteFinderKey(finderSearchKey)
      setRemoteFinderEntries([])
      setRemoteFinderStatus('loading')
      setRemoteFinderError(undefined)
      void Promise.all(
        finderScope.folders.map(async (folder) => {
          const params = new URLSearchParams({
            kind: 'search',
            projectId: finderScope.projectId,
            folderId: folder.id,
            q: query,
          })
          const response = await fetch(`${treeEndpoint}?${params}`, {
            cache: 'no-store',
            signal: controller.signal,
          })
          const body = (await response.json()) as FinderSearchResponse
          if (!response.ok || !body.entries) {
            throw new Error(body.error ?? `Search in ${finderScope.label} failed.`)
          }
          return body.entries.map((entry) => ({
            ...entry,
            path: folder.path,
            caption: `Inside ${folder.path.at(-1)?.name ?? finderScope.label}`,
          }))
        }),
      )
        .then((groups) => {
          if (controller.signal.aborted) return
          setRemoteFinderEntries(uniqueFinderEntries(groups.flat()))
          setRemoteFinderStatus('ready')
        })
        .catch((error: unknown) => {
          if (controller.signal.aborted) return
          setRemoteFinderEntries([])
          setRemoteFinderStatus('error')
          setRemoteFinderError(
            error instanceof Error ? error.message : `Search in ${finderScope.label} failed.`,
          )
        })
    }, 250)

    return () => {
      window.clearTimeout(timer)
      controller.abort()
    }
  }, [finderQuery, finderScope, finderSearchKey, treeEndpoint])

  const remoteFinderMatches = useMemo(() => {
    if (!finderSearchKey || remoteFinderKey !== finderSearchKey) return []
    const loadedIds = new Set(finderEntries.map((entry) => entry.item.id))
    return remoteFinderEntries.filter((entry) => !loadedIds.has(entry.item.id))
  }, [finderEntries, finderSearchKey, remoteFinderEntries, remoteFinderKey])

  const activeRemoteFinderStatus = finderSearchKey
    ? remoteFinderKey === finderSearchKey
      ? remoteFinderStatus
      : 'loading'
    : 'ready'
  const activeRemoteFinderError =
    remoteFinderKey === finderSearchKey ? remoteFinderError : undefined

  const finderPlaceholder = finderScope ? `Search in ${finderScope.label}` : 'Find a loaded file'
  const finderEmptyLabel = finderScope
    ? finderQuery.trim().length < 2
      ? 'Type at least 2 characters to search unopened folders.'
      : `No files match in ${finderScope.label}.`
    : 'Expand a project or folder to search unopened folders.'

  return (
    <SidebarProvider
      className={
        embedded
          ? 'relative h-[36rem] min-h-[36rem] overflow-hidden bg-background'
          : 'h-svh min-h-[32rem] overflow-hidden bg-background'
      }
    >
      <HubSidebar
        finder={{
          query: finderQuery,
          onQueryChange: setFinderQuery,
          groups: [
            { id: 'loaded', label: 'Loaded files', entries: finderEntries },
            {
              id: 'remote',
              label: finderScope ? `In ${finderScope.label}` : 'Project search',
              status: activeRemoteFinderStatus,
              error: activeRemoteFinderError,
              entries: remoteFinderMatches,
            },
          ],
          onItemOpen: ({ item, version }) => openItem(item, version),
          placeholder: finderPlaceholder,
          emptyLabel: finderEmptyLabel,
        }}
        tree={{
          nodes,
          expandedIds,
          selectedId,
          pendingId,
          onExpand: expand,
          onCollapse: (node) => setExpandedIds((current) => current.filter((id) => id !== node.id)),
          onItemOpen: openItem,
        }}
        footer={
          rootPending ? (
            <output className="flex min-h-11 items-center gap-2 px-2 text-muted-foreground text-xs">
              <LoaderCircleIcon aria-hidden className="size-3.5 animate-spin" />
              <span className="group-data-[collapsible=icon]:hidden">Loading hubs</span>
            </output>
          ) : treeError ? (
            <p role="alert" className="px-2 py-2 text-status-danger text-xs">
              {treeError}
            </p>
          ) : null
        }
        collapsible="icon"
        className={
          embedded ? 'border-border border-r md:absolute md:h-full' : 'border-border border-r'
        }
      />

      <SidebarInset
        className={
          embedded
            ? 'h-full min-h-0 min-w-0 overflow-hidden'
            : 'h-svh min-h-0 min-w-0 overflow-hidden'
        }
      >
        <header className="flex min-h-16 shrink-0 items-center gap-3 border-b bg-background px-2 sm:px-4">
          <SidebarTrigger className="size-11 shrink-0" />
          <span className="hidden size-9 shrink-0 place-items-center rounded-lg bg-primary text-primary-foreground sm:grid">
            <Building2Icon aria-hidden className="size-4" />
          </span>
          <div className="min-w-0 flex-1">
            <h1 className="truncate font-heading font-medium text-sm sm:text-base">Model viewer</h1>
            <p className="truncate text-muted-foreground text-xs">
              {selection?.item.name ?? 'Autodesk project models'}
            </p>
          </div>
          <UserAccountBadge account={account} size="sm" className="hidden max-w-52 sm:flex" />
          <form action={signOutHref} method="post" className="shrink-0">
            <Button
              type="submit"
              variant="ghost"
              className="size-11 gap-1.5 px-0 sm:w-auto sm:px-3"
              aria-label="Sign out of Autodesk"
            >
              <LogOutIcon aria-hidden />
              <span className="hidden sm:inline">Sign out</span>
            </Button>
          </form>
        </header>

        <section className="relative min-h-0 min-w-0 flex-1 bg-muted" aria-label="Model viewer">
          {urn && !viewerError ? (
            <APSViewer
              urn={urn}
              getAccessToken={getAccessToken}
              extensions={AEC_STARTER_EXTENSIONS}
              profile="aec"
              toolbar="native"
              radius={0}
              className="size-full"
              onViewerReady={(viewer) => viewer.prefs.set('openPropertiesOnSelect', true)}
              onError={(error) => setViewerError(error.message)}
            />
          ) : (
            <div className="absolute inset-0 grid place-items-center p-6">
              {translation ? (
                <ModelStatusCard translation={translation} className="max-w-lg" />
              ) : (
                <div className="max-w-sm text-center">
                  <h2 className="font-heading font-medium text-xl">Choose a model</h2>
                  <p className="mt-2 text-muted-foreground text-sm">
                    Expand a hub, project, and folder, then open an item to load its tip version.
                  </p>
                </div>
              )}
            </div>
          )}
        </section>
      </SidebarInset>
    </SidebarProvider>
  )
}

export { ModelBrowser }

import { APS_BASE_URL, authHeaders, TokenError } from 'aec-auth'
import { cookies } from 'next/headers'

import type {
  HubTreeFolderNode,
  HubTreeHubNode,
  HubTreeItemNode,
  HubTreeNode,
  HubTreeProjectNode,
  HubTreeVersionNode,
} from '@/components/ui/hub-tree'
import { getSessionToken, openSession, SESSION_COOKIE } from '@/lib/acc-auth'
import {
  type ApsFolderDoc,
  type ApsHubDoc,
  type ApsItemDoc,
  type ApsProjectDoc,
  type ApsVersionDoc,
  fromApsFolder,
  fromApsHub,
  fromApsItem,
  fromApsProject,
  fromApsVersion,
} from '@/lib/aps-data-preset'
import type { Item, ItemVersion } from '@/lib/project-types'

interface JsonApiDocument<T> {
  data?: T
  included?: ApsVersionDoc[]
  links?: { next?: unknown }
}

interface TypedFolderDoc extends ApsFolderDoc {
  type: 'folders'
}

interface TypedItemDoc extends ApsItemDoc {
  type: 'items'
}

interface SearchVersionDoc extends ApsVersionDoc {
  relationships?: ApsVersionDoc['relationships'] & {
    item?: { data?: { id?: string } | null }
  }
}

interface SearchEntry {
  item: Item
  version: ItemVersion
}

type TreeKind = 'hubs' | 'projects' | 'top-folders' | 'folder-contents' | 'versions' | 'search'
type BrowseKind = Exclude<TreeKind, 'search'>

class MissingQueryParameterError extends Error {}

const FOLDER_PAGE_LIMIT = 200
const MAX_FOLDER_PAGES = 20
const SEARCH_MIN_QUERY_LENGTH = 2

function apiBase(origin: string): string {
  const configured = process.env.APS_AUTH_BASE_URL
  if (!configured) return APS_BASE_URL
  return configured.startsWith('/') ? `${origin}${configured}` : configured
}

function segment(value: string): string {
  return encodeURIComponent(value).replaceAll('%3A', ':')
}

async function apsGet<T>(url: string, token: Awaited<ReturnType<typeof getSessionToken>>) {
  const response = await fetch(url, {
    headers: { ...authHeaders(token), Accept: 'application/json' },
    cache: 'no-store',
  })
  if (!response.ok) throw new Error(`${response.status} ${response.statusText}`.trim())
  return (await response.json()) as T
}

function required(searchParams: URLSearchParams, name: string): string {
  const value = searchParams.get(name)
  if (!value) throw new MissingQueryParameterError(`Missing required query parameter: ${name}`)
  return value
}

function hubNode(doc: ApsHubDoc): HubTreeHubNode {
  const value = fromApsHub(doc)
  return { id: `hub:${value.id}`, name: value.name, type: 'hub', value, hasChildren: true }
}

function projectNode(doc: ApsProjectDoc, hubId: string): HubTreeProjectNode {
  const adapted = fromApsProject(doc)
  const value = { ...adapted, hubId: adapted.hubId ?? hubId }
  return {
    id: `project:${hubId}:${value.id}`,
    name: value.name,
    type: 'project',
    value,
    hasChildren: true,
  }
}

function folderNode(doc: ApsFolderDoc, projectId: string): HubTreeFolderNode {
  const value = fromApsFolder(doc)
  return {
    id: `folder:${projectId}:${value.id}`,
    name: value.name,
    type: 'folder',
    value,
    hasChildren: true,
  }
}

function itemNode(doc: ApsItemDoc, projectId: string, tip?: ApsVersionDoc): HubTreeItemNode {
  const value = fromApsItem(doc, tip)
  return {
    id: `item:${projectId}:${value.id}`,
    name: value.name,
    type: 'item',
    value,
    hasChildren: true,
  }
}

function versionNode(doc: ApsVersionDoc, projectId: string, itemId: string): HubTreeVersionNode {
  const value = fromApsVersion(doc)
  return {
    id: `version:${projectId}:${itemId}:${value.id}`,
    name: value.displayName,
    type: 'version',
    value,
    hasChildren: false,
  }
}

async function loadFolderContents(
  base: string,
  token: Awaited<ReturnType<typeof getSessionToken>>,
  projectId: string,
  folderId: string,
): Promise<HubTreeNode[]> {
  const documents: JsonApiDocument<(TypedFolderDoc | TypedItemDoc)[]>[] = []
  for (let page = 0; page < MAX_FOLDER_PAGES; page += 1) {
    const document = await apsGet<JsonApiDocument<(TypedFolderDoc | TypedItemDoc)[]>>(
      `${base}/data/v1/projects/${segment(projectId)}/folders/${segment(folderId)}/contents?page[number]=${page}&page[limit]=${FOLDER_PAGE_LIMIT}`,
      token,
    )
    documents.push(document)
    if (!document.links?.next) break
  }

  const tips = new Map(
    documents.flatMap((document) => document.included ?? []).map((tip) => [tip.id, tip]),
  )
  return documents.flatMap((document) =>
    (document.data ?? []).map((resource) =>
      resource.type === 'folders'
        ? folderNode(resource, projectId)
        : itemNode(resource, projectId, tips.get(resource.relationships?.tip?.data?.id ?? '')),
    ),
  )
}

async function searchFolder(
  base: string,
  token: Awaited<ReturnType<typeof getSessionToken>>,
  projectId: string,
  folderId: string,
  query: string,
): Promise<SearchEntry[]> {
  const documents: JsonApiDocument<SearchVersionDoc[]>[] = []
  for (let page = 0; page < MAX_FOLDER_PAGES; page += 1) {
    const searchUrl = new URL(
      `${base}/data/v1/projects/${segment(projectId)}/folders/${segment(folderId)}/search`,
    )
    searchUrl.searchParams.set('filter[attributes.displayName]-contains', query)
    searchUrl.searchParams.set('page[number]', String(page))
    searchUrl.searchParams.set('page[limit]', String(FOLDER_PAGE_LIMIT))
    const document = await apsGet<JsonApiDocument<SearchVersionDoc[]>>(searchUrl.href, token)
    documents.push(document)
    if (!document.links?.next) break
  }

  return documents.flatMap((document) =>
    (document.data ?? []).flatMap((doc) => {
      const itemId = doc.relationships?.item?.data?.id
      if (!itemId) return []
      const version = fromApsVersion(doc)
      return [
        {
          item: {
            id: itemId,
            name: version.displayName,
            type: 'item' as const,
            tip: version,
            translationStatus: version.derivativeUrn ? ('success' as const) : ('pending' as const),
          },
          version,
        },
      ]
    }),
  )
}

async function loadNodes(
  kind: BrowseKind,
  searchParams: URLSearchParams,
  base: string,
  token: Awaited<ReturnType<typeof getSessionToken>>,
): Promise<HubTreeNode[]> {
  if (kind === 'hubs') {
    const document = await apsGet<JsonApiDocument<ApsHubDoc[]>>(`${base}/project/v1/hubs`, token)
    return (document.data ?? []).map(hubNode)
  }

  const hubId = kind === 'projects' || kind === 'top-folders' ? required(searchParams, 'hubId') : ''
  const projectId = kind === 'projects' ? '' : required(searchParams, 'projectId')

  if (kind === 'projects') {
    const document = await apsGet<JsonApiDocument<ApsProjectDoc[]>>(
      `${base}/project/v1/hubs/${segment(hubId)}/projects`,
      token,
    )
    return (document.data ?? []).map((doc) => projectNode(doc, hubId))
  }

  if (kind === 'top-folders') {
    const document = await apsGet<JsonApiDocument<ApsFolderDoc[]>>(
      `${base}/project/v1/hubs/${segment(hubId)}/projects/${segment(projectId)}/topFolders`,
      token,
    )
    return (document.data ?? []).map((doc) => folderNode(doc, projectId))
  }

  if (kind === 'folder-contents') {
    return loadFolderContents(base, token, projectId, required(searchParams, 'folderId'))
  }

  const itemId = required(searchParams, 'itemId')
  const document = await apsGet<JsonApiDocument<ApsVersionDoc[]>>(
    `${base}/data/v1/projects/${segment(projectId)}/items/${segment(itemId)}/versions?page[limit]=200`,
    token,
  )
  return (document.data ?? []).map((doc) => versionNode(doc, projectId, itemId))
}

/**
 * Lazy, session-authenticated Data Management tree endpoint.
 *
 * GET /api/models/tree?kind=hubs
 * GET /api/models/tree?kind=projects&hubId=...
 * GET /api/models/tree?kind=top-folders&hubId=...&projectId=...
 * GET /api/models/tree?kind=folder-contents&projectId=...&folderId=...
 * GET /api/models/tree?kind=versions&projectId=...&itemId=...
 * GET /api/models/tree?kind=search&projectId=...&folderId=...&q=...
 */
export async function GET(request: Request): Promise<Response> {
  const url = new URL(request.url)
  const kind = url.searchParams.get('kind') as TreeKind | null
  if (
    !kind ||
    !['hubs', 'projects', 'top-folders', 'folder-contents', 'versions', 'search'].includes(kind)
  ) {
    return Response.json({ error: 'Unknown tree request.' }, { status: 400 })
  }

  try {
    const cookieStore = await cookies()
    const session = await openSession(cookieStore.get(SESSION_COOKIE)?.value)
    if (!session) {
      return Response.json({ error: 'Sign in with Autodesk to browse models.' }, { status: 401 })
    }
    const token = await getSessionToken(url.origin, session)
    if (kind === 'search') {
      const query = required(url.searchParams, 'q').trim()
      if (query.length < SEARCH_MIN_QUERY_LENGTH) {
        return Response.json({ entries: [] }, { headers: { 'Cache-Control': 'no-store' } })
      }
      const entries = await searchFolder(
        apiBase(url.origin),
        token,
        required(url.searchParams, 'projectId'),
        required(url.searchParams, 'folderId'),
        query,
      )
      return Response.json({ entries }, { headers: { 'Cache-Control': 'no-store' } })
    }
    const nodes = await loadNodes(kind, url.searchParams, apiBase(url.origin), token)
    return Response.json({ nodes }, { headers: { 'Cache-Control': 'no-store' } })
  } catch (error) {
    if (error instanceof MissingQueryParameterError) {
      return Response.json({ error: error.message }, { status: 400 })
    }
    if (
      error instanceof TokenError &&
      (error.code === 'consent_required' || error.code === 'grant_invalid')
    ) {
      return Response.json(
        { error: 'Reconnect Autodesk to browse models.' },
        { status: 401, headers: { 'Cache-Control': 'no-store' } },
      )
    }
    console.error('Model tree request failed', error)
    return Response.json(
      { error: 'The Autodesk project tree could not be loaded.' },
      { status: 502, headers: { 'Cache-Control': 'no-store' } },
    )
  }
}

import type { TokenSource } from 'aec-auth'
import { apsOAuth, memoryVaultStore, vaultTokenSource } from 'aec-auth/vault'
import { connection } from 'next/server'

const VIEWER_SCOPES = ['viewables:read'] as const
let tokenSource: TokenSource | undefined

function getViewerTokenSource(): TokenSource {
  if (tokenSource) return tokenSource
  const clientId = process.env.APS_CLIENT_ID
  const clientSecret = process.env.APS_CLIENT_SECRET
  if (!clientId || !clientSecret) throw new Error('APS viewer credentials are not configured')
  tokenSource = vaultTokenSource({
    store: memoryVaultStore(),
    providers: { aps: apsOAuth({ clientId, clientSecret }) },
  })
  return tokenSource
}

/** A 2-legged viewer token with the minimum Model Derivative read scope. */
export async function GET(): Promise<Response> {
  await connection()
  try {
    const token = await getViewerTokenSource().getToken({
      provider: 'aps',
      subject: { type: 'app' },
      scopes: VIEWER_SCOPES,
    })
    return Response.json(
      {
        accessToken: token.token,
        expiresInSeconds: Math.max(1, Math.floor((token.expiresAt - Date.now()) / 1000)),
      },
      { headers: { 'Cache-Control': 'no-store' } },
    )
  } catch (error) {
    console.error('Viewer token request failed', error)
    return Response.json(
      { error: 'The viewer token is unavailable.' },
      { status: 503, headers: { 'Cache-Control': 'no-store' } },
    )
  }
}
